    blocks = {
        0x30: IRBlock(0x30, [Assign(Var("local_8"), score), Assign(Var("local_10"), quotient), Branch(Bin(">u", Var("local_10"), Const(4)), 0x9A, 0x62)], [0x30, 0x31, 0x34, 0x37, 0x3B, 0x42, 0x45, 0x49, 0x4B, 0x4F, 0x51, 0x53, 0x57, 0x59, 0x5D, 0x60]),
